(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const stage=document.querySelector('.kinetic-stage'),playground=document.querySelector('.power-playground');let x=0,y=0,startX=0,startY=0,baseX=0,baseY=0,dragging=false,frame;const clamp=(v,min,max)=>Math.max(min,Math.min(v,max));function render(){playground?.style.setProperty('--rx',`${y}deg`);playground?.style.setProperty('--ry',`${x}deg`)}
if(stage){stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;dragging=true;stage.classList.add('is-dragging');stage.setPointerCapture(e.pointerId);startX=e.clientX;startY=e.clientY;baseX=x;baseY=y});stage.addEventListener('pointermove',e=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(dragging){x=clamp(baseX+(e.clientX-startX)*.25,-40,40);y=clamp(baseY-(e.clientY-startY)*.2,-25,25)}else if(!reduced&&e.pointerType!=='touch'){const r=stage.getBoundingClientRect();x=((e.clientX-r.left)/r.width-.5)*18;y=-((e.clientY-r.top)/r.height-.5)*14}render()})});const release=()=>{dragging=false;stage.classList.remove('is-dragging')};stage.addEventListener('pointerup',release);stage.addEventListener('pointercancel',release);stage.addEventListener('lostpointercapture',release);stage.addEventListener('pointerleave',()=>{if(!dragging){cancelAnimationFrame(frame);x=y=0;render()}});stage.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','r','R'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')x=clamp(x-8,-40,40);if(e.key==='ArrowRight')x=clamp(x+8,-40,40);if(e.key==='ArrowUp')y=clamp(y+8,-25,25);if(e.key==='ArrowDown')y=clamp(y-8,-25,25);if(e.key.toLowerCase()==='r')x=y=0;render()})}
const moods=[['linear-gradient(135deg,#6eb9f7,#a38bef)','#c9b8f1','Blue voltage'],['#ffb17e','#c9d7f1','Apricot orange'],['#d1c1ee','#d1ec97','Lilac purple'],['#c8e5f1','#ffc09c','Sky blue']];let mood=0;document.querySelector('.mood-switch')?.addEventListener('click',()=>{mood=(mood+1)%moods.length;const [bg,disc,name]=moods[mood];document.documentElement.style.setProperty('--play',bg.startsWith('linear-gradient')?'#6eb9f7':bg);document.documentElement.style.setProperty('--play-surface',bg);document.documentElement.style.setProperty('--lavender',disc);document.querySelector('.mood-status').textContent=`${name} mood selected.`;if(!reduced){x+=12;render();setTimeout(()=>{x=0;render()},450)}});
document.querySelectorAll('a').forEach(a=>{if(a.origin!==location.origin||a.hash||a.hasAttribute('download')||a.target==='_blank')return;a.addEventListener('click',e=>{if(reduced||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0)return;e.preventDefault();document.body.classList.remove('leaving');document.body.classList.add('is-exiting');setTimeout(()=>location.href=a.href,340)})});addEventListener('pageshow',()=>document.body.classList.remove('is-exiting','leaving'));
})();
